    gemm::proc_tile_q(device, &x_dm, q1, &sq, &mut yq, 1);
    gemm::proc_tile_q(device, &x_dm, q2, &sq, &mut yq, 2);
    gemm::proc_tile_q(device, &x_dm, q3, &sq, &mut yq, 3);

